def metric_panel(a):
 b=(a==2).astype(int)
 # features
 f={'n':int(b.sum()), 'row':tuple(b.sum(1)), 'col':tuple(b.sum(0)), 'diag':int(np.trace(b)+np.trace(np.fliplr(b))), 'corners':int(b[0,0]+b[0,-1]+b[-1,0]+b[-1,-1]), 'center':int(b[1:3,1:3].sum()), 'adj':int(sum(np.sum(b[:,:-1]*b[:,1:])+np.sum(b[:-1,:]*b[1:,:]))), 'full2':0}
 f['full2']=sum(int(b[i:i+2,j:j+2].sum()==4) for i in range(3) for j in range(3))
 f['empty_rows']=int(any(x==0 for x in b.sum(1)));f['empty_cols']=int(any(x==0 for x in b.sum(0)))
 f['even_rows']=int(all(x%2==0 for x in b.sum(1))); f['even_cols']=int(all(x%2==0 for x in b.sum(0)))
 # symmetry mismatch counts
 f['h_mis']=int(np.sum(b != np.flipud(b)));f['v_mis']=int(np.sum(b != np.fliplr(b)));f['r180_mis']=int(np.sum(b != np.rot90(b,2)))
 return f
